"use strict";
exports.inherited = (v) =>
  [
    String(v),
    `${v}`,
    v.constructor === Object,
    v.hasOwnProperty("a"),
    v.hasOwnProperty("toString"),
    Object.hasOwn(v, "toString"),
    "toString" in v,
    v.valueOf() === v,
    typeof v.isPrototypeOf,
    v.toString === Object.prototype.toString,
  ].join(" ");
exports.ownToString = (v) => [String(v), `${v}`, v.hasOwnProperty("n")].join(" ");
exports.record = () => ({ a: 1, b: "x" });
exports.table = () => ({ a: 1 });
exports.list = () => [1, 2, 3];
exports.listValue = () => [1, 2, 3];
exports.map = () => new Map([["a", 1]]);
exports.date = () => new Date(1700000000123);
exports.pattern = () => /a+/g;
exports.failure = () => new RangeError("island");
let kept = null;
exports.keep = () => (kept = { n: 1, tags: ["t"], when: new Date(5) });
exports.bare = () => Object.assign(Object.create(null), { x: 1 });
exports.isKept = (v) => v === kept;
exports.keptN = () => kept.n;
exports.describe = (v) => `${Object.keys(v).join(",")}|${v.n}|${v.tags.join("+")}|${v.when.getTime()}`;
